<?php
namespace Database\Seeders; use App\Models\{Property,RatePlan,Room,RoomType}; use App\Models\User; use Illuminate\Database\Seeder; use Illuminate\Support\Facades\Hash;
class HotelFoundationSeeder extends Seeder { public function run(): void { $property=Property::firstOrCreate(['code'=>env('HMS_PROPERTY_CODE','MAIN')],['name'=>env('HMS_PROPERTY_NAME','Main Hotel'),'currency'=>env('HMS_CURRENCY','UGX'),'timezone'=>env('HMS_TIMEZONE','Africa/Kampala')]); User::firstOrCreate(['email'=>env('HMS_ADMIN_EMAIL','admin@example.com')],['name'=>env('HMS_ADMIN_NAME','System Administrator'),'password'=>Hash::make(env('HMS_ADMIN_PASSWORD','ChangeMe123!')),'property_id'=>$property->id,'role'=>'super_admin','is_active'=>true]); $type=RoomType::firstOrCreate(['property_id'=>$property->id,'code'=>'STD'],['name'=>'Standard Room','base_occupancy'=>1,'max_adults'=>2,'max_children'=>1,'base_rate'=>150000,'is_active'=>true]); RatePlan::firstOrCreate(['property_id'=>$property->id,'code'=>'BAR-STD'],['room_type_id'=>$type->id,'name'=>'Best Available Rate','nightly_rate'=>150000,'is_active'=>true]); foreach(range(101,105) as $no) Room::firstOrCreate(['property_id'=>$property->id,'room_number'=>(string)$no],['room_type_id'=>$type->id,'floor'=>'1','status'=>'available','housekeeping_status'=>'clean','is_active'=>true]); } }
